//go.hanyang.ac.kr/web/rate/rate.do?m_type=SUSI","\uace0\ub824\ub300_\uc785\ud559\ucc98":"https://oku.korea.ac.kr","\uc131\uade0\uad00\ub300_\uae30\ucd9c":"https://admission.skku.edu/admission/html/rolling/question.html","\uc11c\uac15\ub300_\uc218\uc2dc\uacbd\uc7c1\ub960":"https://admission.sogang.ac.kr/enter/html/rolling/competition.asp","\uc5f0\uc138\ub300_\uacbd\uc7c1\ub960":"https://addon.jinhakapply.com/RatioV1/RatioH/Ratio11080571.html","_note":"\uac01 \ub300\ud559\uc774 \ub9e4\ub144 4~5\uc6d4\uacbd \uc785\ud559\ucc98\uc5d0 \uac8c\uc2dc\ud558\ub294 '\uc785\uc2dc\uacb0\uacfc' \uacf5\uc9c0\uac00 \uac00\uc7a5 \uc815\ud655\ud55c \uc6d0\uc790\ub8cc"},"_\uae30\uc900":"\uc790\ub8cc \uc2e0\ube59\uc131 \uae30\uc900: \uc62c\ud574(2026\ub144) \uc6f9\uc5d0 \uac8c\uc2dc\u00b7\uac31\uc2e0\ub41c \uc790\ub8cc\ub9cc \uc0ac\uc6a9\ud55c\ub2e4. \uad6c \uc81c\ub3c4 \uc2dc\uc808 \uc790\ub8cc\ub294 \uc81c\ub3c4\uac00 \ub2ec\ub77c \uc624\ud310\uc744 \ubd80\ub974\ubbc0\ub85c \uc81c\uc678\ud55c\ub2e4. \uace0\ub824\ub300 2015 \ub300\uc785\uc124\uba85\ud68c \uc790\ub8cc(\uacf5\ub300 50~60\uc810\ub300)\ub294 \uc774 \uae30\uc900\uc73c\ub85c \uc0ad\uc81c\ud568 \u2014 \ub2f9\uc2dc \ub17c\uc220\uc740 2016\ud559\ub144\ub3c4\ub85c \ud3d0\uc9c0\ub410\uace0 2025\ud559\ub144\ub3c4\uc5d0 \ub2e4\ub978 \uc81c\ub3c4\ub85c \ubd80\ud65c\ud588\ub2e4."},"\uc2e4\uc9c8\uacbd\uc7c1\ub960_\ud574\uc11d":{"\ud575\uc2ec":"\uba85\ubaa9 \uacbd\uc7c1\ub960\uc740 \ud5c8\uc218\ub2e4. \uacb0\uc2dc + \uc218\ub2a5\ucd5c\uc800 \ubbf8\ucda9\uc871\uc774 \ube60\uc9c0\uba74 \uc2e4\uc9c8\uc740 \uc808\ubc18 \uc774\ud558\ub85c \ub5a8\uc5b4\uc9c4\ub2e4.","\uacb0\uc2dc\uc728":"\uc790\uc5f0\uacc4\ub294 \uc778\ubb38\uacc4\ubcf4\ub2e4 \uacb0\uc2dc\uc728\uc774 \ub0ae\ub2e4(\uc218\ud559 \ub17c\uc220 \ud2b9\uc131\uc0c1 \uc9c0\uc6d0\uc790 \ubab0\uc785\ub3c4\uac00 \ub192\uc74c). \uc778\ubb38 \uc0ac\ub840 \uacb0\uc2dc\uc728 57.3%(31:1\u21925.8:1), \uc790\uc5f0 \uc0ac\ub840 34%(52.7:1\u219223.1:1)","\ucd5c\uc800_\ubcc0\uc218":"\uc5f0\uc138